import{_ as t,o as d,c as a,a0 as r}from"./chunks/framework.BGyYNsHo.js";const p=JSON.parse('{"title":"Scripts, benchmarks y verificación","description":"","frontmatter":{},"headers":[],"relativePath":"es/reference/07-scripts-y-benchmarks.md","filePath":"es/reference/07-scripts-y-benchmarks.md"}'),o={name:"es/reference/07-scripts-y-benchmarks.md"};function s(c,e,n,i,l,m){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="scripts-benchmarks-y-verificacion" tabindex="-1">Scripts, benchmarks y verificación <a class="header-anchor" href="#scripts-benchmarks-y-verificacion" aria-label="Permalink to &quot;Scripts, benchmarks y verificación&quot;">​</a></h1><p>El conjunto de scripts de prueba y verificación en <code>scripts/</code> — qué hace cada uno y cómo ejecutarlo.</p><p>Todos se ejecutan desde la raíz del repo con <code>node scripts/&lt;name&gt;.mjs</code>. El patrón común: shim de <code>globalThis.self/window</code>, cargar <code>public/swmm6wasm.js</code>, instanciar <code>swmm6wasm.wasm</code> en Node y envolver la API C con <code>Module.cwrap</code>. Varios levantan <code>server.py</code> + una instancia de Chrome vía CDP.</p><h2 id="benchmarks-y-probes-motor-en-node" tabindex="-1">Benchmarks y probes (motor en Node) <a class="header-anchor" href="#benchmarks-y-probes-motor-en-node" aria-label="Permalink to &quot;Benchmarks y probes (motor en Node)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Propósito</th><th>Uso</th></tr></thead><tbody><tr><td><code>bench-1d-bellinge.mjs</code></td><td>Costos por-stride y por-window en el modelo Bellinge; proyecta 48 h de wall time</td><td>sin args</td></tr><tr><td><code>bench-1d.mjs</code></td><td>Benchmark 1D de stride puro; salida JSON</td><td><code>node bench-1d.mjs &lt;inp&gt; [--wasm &lt;path&gt;] [--tag &lt;l&gt;] [--keep-vs]</code></td></tr><tr><td><code>probe-1d.mjs</code></td><td>Volcado de head/depth por paso de uniones (limitado a 80 pasos)</td><td><code>node probe-1d.mjs &lt;inp&gt;</code></td></tr><tr><td><code>probe-1d-nan.mjs</code></td><td>Corrida 1D completa de 48 h escaneando heads/depths/volúmenes por anomalías NaN/Inf</td><td><code>node probe-1d-nan.mjs [VS]</code></td></tr><tr><td><code>bench-wasm-threads.mjs</code></td><td><strong>Benchmark del motor con hilos:</strong> ejecuta <code>simWorker.js</code> en Chrome con aislamiento cross-origin a THREADS 1 vs N; reporta wall time + continuidad bit-idéntica</td><td><code>node bench-wasm-threads.mjs [--inp &lt;p&gt;] [--threads 1,4] [--minutes &lt;n&gt;]</code></td></tr></tbody></table><h2 id="harnesses-end-to-end-chrome-cdp-y-pruebas-unitarias" tabindex="-1">Harnesses end-to-end Chrome/CDP y pruebas unitarias <a class="header-anchor" href="#harnesses-end-to-end-chrome-cdp-y-pruebas-unitarias" aria-label="Permalink to &quot;Harnesses end-to-end Chrome/CDP y pruebas unitarias&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Propósito</th><th>Puerto</th><th>Uso</th></tr></thead><tbody><tr><td><code>test-network3d.mjs</code></td><td>Suite de pruebas unitarias para la geometría de red 3D (generación de polígonos, trayectorias de enlaces, mapeo de entidades)</td><td>—</td><td><code>npm run test:3d</code></td></tr><tr><td><code>verify-bellinge.mjs</code></td><td><strong>Gate de verificación automatizada:</strong> Chrome headless carga la app, carga Bellinge Web, corre la simulación vía <code>simWorker.js</code> y verifica la continuidad de salida</td><td>CDP 9222</td><td>sin args; escribe <code>scripts/verify-out/</code></td></tr><tr><td><code>verify-1d-split.mjs</code></td><td>Gate de regresión para la pierna de simulación 1D; verifica heads hidráulicos finitos</td><td>—</td><td><code>node verify-1d-split.mjs &lt;inp&gt; [--wasm &lt;p&gt;] [--tol &lt;%&gt;] [--hours &lt;n&gt;] [--json]</code></td></tr><tr><td><code>verify-lchar.mjs</code></td><td>Verificación de longitud característica</td><td>—</td><td><code>node verify-lchar.mjs &lt;inp&gt;</code></td></tr></tbody></table>',7)])])}co